contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(address(this).balance >= amount);

        uint balBefore = address(c).balance;
        uint countBefore = c.depositsCount(); if (__ESBMC_reverted()) return;

        bool reverted;
        c.sendMoney(address(this), amount); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }

        assert(reverted ? (address(c).balance == balBefore && c.depositsCount() == countBefore) : (address(c).balance == balBefore - amount && c.depositsCount() == countBefore));
    }

    receive() external payable {}
}

